<?php $rows=$data['deliveries']??[];?>
<div class="module-stack"><?php if(!empty($data['notice'])):?><div class="notice success"><?=e($data['notice']['message']??'Completed.')?></div><?php endif;?><section class="card table-card"><h2>Delivery pickings</h2><div class="table-responsive"><table class="data-table"><thead><tr><th>Picking</th><th>Sales Order</th><th>Customer</th><th>Requested</th><th>Reserved</th><th>Done</th><th>Remaining</th><th>State</th></tr></thead><tbody><?php if($rows===[]):?><tr><td colspan="8">No Sales delivery pickings.</td></tr><?php endif;?><?php foreach($rows as $row):$remaining=max(0,(float)$row['requested_quantity']-(float)$row['completed_quantity']);?><tr><td><a href="/office_app/public/sales/deliveries/<?=e($row['picking_id'])?>"><?=e($row['picking_number'])?></a><?php if(!empty($row['backorder_of_id'])):?> <span class="status-badge">Backorder</span><?php endif;?></td><td><a href="/office_app/public/sales/orders/<?=e($row['sales_order_id'])?>"><?=e($row['order_number'])?></a></td><td><?=e($row['customer_name'])?></td><td><?=e($row['requested_quantity'])?></td><td><?=e($row['reserved_quantity'])?></td><td><?=e($row['completed_quantity'])?></td><td><?=e($remaining)?></td><td><?=e(str_replace('_',' ',$row['status']))?></td></tr><?php endforeach;?></tbody></table></div></section></div>
